contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(address newOwner) public payable {
        // read owner before
        address ownerBefore = c.owner(); if (__ESBMC_reverted()) return;
        bool reverted;
        bool ret;
        bool r = c.setOwner(newOwner); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
            ret = false;
        } else {
            reverted = false;
            ret = r;
        }
        // After the call, read owner
        address ownerAfter = c.owner(); if (__ESBMC_reverted()) return;
        // General invariant: if call reverted then it cannot have returned true; if it didn't revert it must have returned true and owner equals newOwner.
        assert((reverted == false && ret == true && ownerAfter == newOwner) || (reverted == true && ret == false && ownerAfter == ownerBefore));
    }
    receive() external payable {}
}

